export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type FailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

export type CarrierRejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly CarrierRejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly CarrierRejection[];
  }>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type ErrorBody =
  | Readonly<{ code: "invalid_command" | "not_found" | "service_unavailable" }>
  | AbortBody;

export type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: AbortClassification;
  rejections: readonly CarrierRejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body: PublicShipment | ErrorBody;
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{
      op: "dispatch";
      shipmentId: string;
      nowMs: number;
      recipient: Recipient;
    }>;

type Confirmation = Readonly<{
  provider: Provider;
  bookingId: string;
}>;

type CarrierAttemptResult =
  | Readonly<{ kind: "confirmed"; confirmation: Confirmation }>
  | Readonly<{ kind: "refused"; rejection: CarrierRejection }>
  | Readonly<{ kind: "throttled"; retryAtMs: number }>
  | Readonly<{ kind: "aborted"; classification: Exclude<AbortClassification, "repository_failure"> }>;

const allowedReasons = ["unsupported_route", "unsupported_parcel"] as const;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return allowedReasons.some((reason) => reason === value);
}

function parseRejection(value: unknown): CarrierRejection | undefined {
  if (!isObject(value) || !isProvider(value.provider) || !isRefusalReason(value.reason)) {
    return undefined;
  }
  return { provider: value.provider, reason: value.reason };
}

function parseRejections(value: unknown): readonly CarrierRejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const parsed = value.map(parseRejection);
  if (parsed.some((rejection) => rejection === undefined)) {
    return undefined;
  }
  return parsed.filter((rejection) => rejection !== undefined);
}

function parseBaseShipmentFields(value: Record<string, unknown>): ShipmentFields | undefined {
  if (
    value.schemaVersion === 1 &&
    typeof value.id === "string" &&
    typeof value.routeCode === "string" &&
    value.routeCode.length > 0 &&
    typeof value.parcelGrams === "number" &&
    Number.isSafeInteger(value.parcelGrams) &&
    value.parcelGrams > 0
  ) {
    return {
      schemaVersion: 1,
      id: value.id,
      routeCode: value.routeCode,
      parcelGrams: value.parcelGrams,
    };
  }
  return undefined;
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  const base = parseBaseShipmentFields(value);
  if (base === undefined) {
    return undefined;
  }

  if (value.state === "queued") {
    return { ...base, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    value.bookingId.length > 0 &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...base,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...base,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return { ...base, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return { ...fields, state: "unavailable", rejections: shipment.rejections };
  }
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function abortResponse(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: readonly CarrierRejection[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections,
    },
  };
}

function abortEvent(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: readonly CarrierRejection[],
): Record<string, unknown> {
  return {
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections,
  };
}

function isValidRetryAt(value: unknown, nowMs: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > nowMs;
}

function classifyAtlasRejection(value: unknown, nowMs: number): CarrierAttemptResult {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    return isRefusalReason(value.reason)
      ? { kind: "refused", rejection: { provider: "atlas", reason: value.reason } }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    return isValidRetryAt(value.retryAtMs, nowMs)
      ? { kind: "throttled", retryAtMs: value.retryAtMs }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyBeaconRejection(value: unknown, nowMs: number): CarrierAttemptResult {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (!isObject(value.details)) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return isRefusalReason(value.details.reason)
      ? { kind: "refused", rejection: { provider: "beacon", reason: value.details.reason } }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    if (!isObject(value.details)) {
      return { kind: "aborted", classification: "invalid_provider_response" };
    }
    return isValidRetryAt(value.details.retryAtMs, nowMs)
      ? { kind: "throttled", retryAtMs: value.details.retryAtMs }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyConfirmation(provider: Provider, value: unknown): CarrierAttemptResult {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (provider === "atlas" && typeof value.bookingId === "string" && value.bookingId.length > 0) {
    return {
      kind: "confirmed",
      confirmation: { provider: "atlas", bookingId: value.bookingId },
    };
  }
  if (provider === "beacon" && typeof value.reference === "string" && value.reference.length > 0) {
    return {
      kind: "confirmed",
      confirmation: { provider: "beacon", bookingId: value.reference },
    };
  }
  return { kind: "aborted", classification: "invalid_provider_response" };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierAttemptResult> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return classifyConfirmation(provider, confirmation);
  } catch (rejected) {
    return provider === "atlas"
      ? classifyAtlasRejection(rejected, nowMs)
      : classifyBeaconRejection(rejected, nowMs);
  }
}

function hasRefusalFor(provider: Provider, rejections: readonly CarrierRejection[]): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

export function createShippingService(dependencies: ShippingDependencies) {
  function emitAbort(
    shipmentId: string,
    failedAt: FailedAt,
    classification: AbortClassification,
    rejections: readonly CarrierRejection[],
  ): ServiceResponse {
    dependencies.logger.info(abortEvent(shipmentId, failedAt, classification, rejections));
    return abortResponse(shipmentId, failedAt, classification, rejections);
  }

  async function saveDecision(
    shipment: StoredShipment,
    record: StoredShipment,
    event: Record<string, unknown>,
    rejections: readonly CarrierRejection[],
  ): Promise<ServiceResponse> {
    try {
      await dependencies.repository.save(shipment.id, record);
    } catch {
      return emitAbort(shipment.id, "repository", "repository_failure", rejections);
    }
    dependencies.logger.info(event);
    const body = publicShipment(record);
    if (record.state === "deferred") {
      return { status: 202, body };
    }
    if (record.state === "unavailable") {
      return { status: 422, body };
    }
    return { status: 200, body };
  }

  async function persistDispatch(
    shipment: StoredShipment,
    confirmation: Confirmation,
    nowMs: number,
    rejections: readonly CarrierRejection[],
  ): Promise<ServiceResponse> {
    const dispatched: DispatchedShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "dispatched",
      provider: confirmation.provider,
      bookingId: confirmation.bookingId,
      dispatchedAtMs: nowMs,
    };
    const response = await saveDecision(
      shipment,
      dispatched,
      {
        shipmentId: shipment.id,
        action: "dispatched",
        provider: confirmation.provider,
      },
      rejections,
    );
    return response;
  }

  async function persistDeferred(
    shipment: StoredShipment,
    provider: Provider,
    retryAtMs: number,
    rejections: readonly CarrierRejection[],
  ): Promise<ServiceResponse> {
    const deferred: DeferredShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "deferred",
      nextProvider: provider,
      retryAtMs,
      rejections,
    };
    const response = await saveDecision(
      shipment,
      deferred,
      {
        shipmentId: shipment.id,
        action: "deferred",
        provider,
        retryAtMs,
        rejections,
      },
      rejections,
    );
    return response;
  }

  async function persistUnavailable(
    shipment: StoredShipment,
    rejections: readonly CarrierRejection[],
  ): Promise<ServiceResponse> {
    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections,
    };
    const response = await saveDecision(
      shipment,
      unavailable,
      {
        shipmentId: shipment.id,
        action: "unavailable",
        rejections,
      },
      rejections,
    );
    return response;
  }

  async function dispatchFrom(
    shipment: QueuedShipment | DeferredShipment,
    command: Extract<Command, { op: "dispatch" }>,
  ): Promise<ServiceResponse> {
    let nextProvider: Provider = shipment.state === "deferred" ? shipment.nextProvider : "atlas";
    let rejections: readonly CarrierRejection[] =
      shipment.state === "deferred" ? shipment.rejections : [];

    if (hasRefusalFor(nextProvider, rejections)) {
      return emitAbort(shipment.id, nextProvider, "invalid_provider_response", rejections);
    }

    const firstAttempt = await attemptCarrier(
      dependencies,
      nextProvider,
      providerRequest(shipment, command.recipient),
      command.nowMs,
    );

    switch (firstAttempt.kind) {
      case "confirmed":
        return persistDispatch(shipment, firstAttempt.confirmation, command.nowMs, rejections);
      case "throttled":
        return persistDeferred(shipment, nextProvider, firstAttempt.retryAtMs, rejections);
      case "aborted":
        return emitAbort(shipment.id, nextProvider, firstAttempt.classification, rejections);
      case "refused":
        rejections = [...rejections, firstAttempt.rejection];
        if (nextProvider === "beacon") {
          return persistUnavailable(shipment, rejections);
        }
        nextProvider = "beacon";
    }

    if (hasRefusalFor(nextProvider, rejections)) {
      return persistUnavailable(shipment, rejections);
    }

    const beaconAttempt = await attemptCarrier(
      dependencies,
      "beacon",
      providerRequest(shipment, command.recipient),
      command.nowMs,
    );

    switch (beaconAttempt.kind) {
      case "confirmed":
        return persistDispatch(shipment, beaconAttempt.confirmation, command.nowMs, rejections);
      case "throttled":
        return persistDeferred(shipment, "beacon", beaconAttempt.retryAtMs, rejections);
      case "refused":
        return persistUnavailable(shipment, [...rejections, beaconAttempt.rejection]);
      case "aborted":
        return emitAbort(shipment.id, "beacon", beaconAttempt.classification, rejections);
    }
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let rawShipment: unknown;
    try {
      rawShipment = await dependencies.repository.get(command.shipmentId);
    } catch {
      return emitAbort(command.shipmentId, "repository", "repository_failure", []);
    }
    if (rawShipment === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(rawShipment);
    if (shipment === undefined) {
      return emitAbort(command.shipmentId, "repository", "repository_failure", []);
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }
    return dispatchFrom(shipment, command);
  }

  return { handle };
}
